/**
 * Derive: scripts/.cache/uttamkumar-filmography.json (from
 * fetch-uttamkumar-filmography.mjs) -> the two committed generated files a
 * real build depends on. Same split as prepare-suman.mjs: the cache is raw
 * ingest, gitignored; these are the clean, typed, reviewed output.
 *
 * films.generated.ts carries every credited acting role Wikipedia's own
 * filmography table lists — 211 titles, 1948 to the 2024 archival-footage
 * release Oti Uttam — as bare structural fact (year, title, role, a note).
 * It is deliberately thin: src/data/uttamkumar/films.ts layers editorial
 * judgement (synopsis, director, co-stars, award/box-office note) onto the
 * subset of these that are actually documented well enough to write a real
 * page about, the same "generated fact + hand-written judgement" split
 * catalogue.ts uses for Kabir Suman's albums.
 *
 * Usage: node scripts/prepare-uttamkumar.mjs
 */
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const CACHE = path.join(ROOT, "scripts", ".cache", "uttamkumar-filmography.json");
const OUT_DIR = path.join(ROOT, "src", "data", "uttamkumar");

function tsString(s) {
  return JSON.stringify(s ?? "");
}

function main() {
  const data = JSON.parse(fs.readFileSync(CACHE, "utf8"));
  const films = data.acting;

  // dedupe any slug collision (two same-titled films in the same year would
  // otherwise silently shadow each other) by suffixing a running index
  const seen = new Map();
  for (const f of films) {
    const n = (seen.get(f.slug) ?? 0) + 1;
    seen.set(f.slug, n);
    if (n > 1) f.slug = `${f.slug}-${n}`;
  }

  const years = films.map((f) => f.year).filter(Boolean);
  const firstYear = Math.min(...years);
  const latestYear = Math.max(...years);

  const filmLines = films
    .map(
      (f) =>
        `  { order: ${f.order}, slug: ${tsString(f.slug)}, year: ${f.year}, title: ${tsString(f.title)}, role: ${tsString(f.role)}, note: ${tsString(f.note)} },`,
    )
    .join("\n");

  const filmsTs = `/**
 * GENERATED by scripts/prepare-uttamkumar.mjs from
 * scripts/fetch-uttamkumar-filmography.mjs's cache. Do not edit by hand —
 * edit src/data/uttamkumar/films.ts for editorial content instead, or
 * re-run the ingest if Wikipedia's own table has changed.
 *
 * Source: ${data.source}
 * Fetched: ${data.fetched}
 */
export interface ArchiveFilm {
  /** position in Wikipedia's own filmography table, 1948 first */
  order: number;
  slug: string;
  year: number;
  title: string;
  /** role/character, when the source article names one */
  role: string;
  /** the source table's own "Notes" cell, verbatim (e.g. "First film opposite Suchitra Sen") */
  note: string;
}

export const ARCHIVE_FILMS: ArchiveFilm[] = [
${filmLines}
];

export const ARCHIVE_FILM_BY_SLUG: Record<string, ArchiveFilm> = Object.fromEntries(
  ARCHIVE_FILMS.map((f) => [f.slug, f]),
);
`;

  fs.mkdirSync(OUT_DIR, { recursive: true });
  fs.writeFileSync(path.join(OUT_DIR, "films.generated.ts"), filmsTs);

  const countsTs = `/**
 * GENERATED by scripts/prepare-uttamkumar.mjs. Do not edit by hand.
 *
 * Pulled out of films.generated.ts (a ~${Math.round(fs.statSync(path.join(OUT_DIR, "films.generated.ts")).size / 1024)}KB file) because
 * src/data/seo.ts reaches these two numbers eagerly, from every page, and
 * should not pull in all 211 rows to do it — the same reasoning
 * kabirsuman/counts.generated.ts gives for the same split.
 */
export const TOTAL_FILMS = ${films.length};
export const FIRST_YEAR = ${firstYear};
export const LATEST_YEAR = ${latestYear};
`;
  fs.writeFileSync(path.join(OUT_DIR, "counts.generated.ts"), countsTs);

  console.log(`wrote films.generated.ts (${films.length} films, ${firstYear}–${latestYear})`);
  console.log(`wrote counts.generated.ts`);
}

main();
